import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminAddProf = () => {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [morada, setMorada] = useState("");
  const [contacto, setContacto] = useState("");

  const salvarProfessor = () => {
    // Lógica para salvar o professor
    console.log("Professor salvo:", { nome, email, morada, contacto });
    // Limpar campos após salvar
    setNome("");
    setEmail("");
    setMorada("");
    setContacto("");
  };

  const cancelar = () => {
    // Lógica para cancelar a adição
    setNome("");
    setEmail("");
    setMorada("");
    setContacto("");
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary">EdunetWeb</h1>
      <ul className="nav nav-tabs mt-3">
        <li className="nav-item">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="mt-3">
        <h3>Adicionar Professor</h3>
        <form>
          <div className="form-group">
            <label>Nome</label>
            <input
              type="text"
              className="form-control"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input
              type="email"
              className="form-control"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>Morada</label>
            <input
              type="text"
              className="form-control"
              value={morada}
              onChange={(e) => setMorada(e.target.value)}
            />
          </div>
          <div className="form-group">
            <label>Contacto</label>
            <input
              type="text"
              className="form-control"
              value={contacto}
              onChange={(e) => setContacto(e.target.value)}
            />
          </div>
          <button
            type="button"
            className="btn btn-danger mt-3"
            onClick={cancelar}
          >
            Cancelar
          </button>
          <button
            type="button"
            className="btn btn-primary mt-3 ml-2"
            onClick={salvarProfessor}
          >
            Salvar
          </button>
        </form>
      </div>
    </div>
  );
};

export default AdminAddProf;
